// Turn the Gmail message into plain text for the AI, and read the shadow-mode switch.
// Shadow mode defaults to ON: nothing is written to the Tickets sheet until you turn it off.
let flag;
try { flag = $vars.M1_SHADOW_MODE; } catch (e) {}
if (flag === undefined || flag === null || flag === '') { try { flag = $env.M1_SHADOW_MODE; } catch (e) {} }
const shadow = String(flag ?? 'true').toLowerCase() !== 'false';

const m = $json;
const from = m.from?.text || m.from?.value?.[0]?.address || m.from || '';
const subject = m.subject || '';
const body = (m.text || m.textAsHtml || m.snippet || '').toString().replace(/\r/g, '').trim();
return {
  json: {
    message_id: m.id || m.messageId || '',
    received_at: m.date || new Date().toISOString(),
    from: String(from), subject, shadow,
    email_text: `From: ${from}\nSubject: ${subject}\n\n${body}`.slice(0, 20000),
  },
};

