  max_tokens: 1024,
  system: 'You are the intake assistant for a home service company (HVAC, plumbing, appliance repair). Read the work-order email and reply with ONLY a JSON object, no prose.',
  messages: [{ role: 'user', content: 'Vendors: Northstar Home Warranty (V1, claims NS-######), Bluepeak Protection Plans (V2, claims BP#######), Harbor Appliance Care (V3, claims HAC-#####), direct customer (V0).\nReturn JSON with keys: customerName, phones (array, "(555) 013-5521" format), address (street only), zip, claimNumber, claimToFollow (true if the email says the claim number will follow), vendorId, trade (HVAC|Plumbing|Appliance), equipment, problemSummary (one sentence), urgency (Emergency|High|Normal). Use null when a value is not in the email. Do not invent data.\n\nEMAIL:\n' + $json.email_text }]
}) }}

