// Read Claude's JSON reply. If it is not valid JSON, keep the email and send it to a person.
const res = $json;
const text = (res.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
const src = $('Build email text').item.json;
let f = {}, parse_error = '';
try { f = JSON.parse(text.replace(/```(?:json)?/g, '').match(/\{[\s\S]*\}/)[0]); }
catch (e) { parse_error = 'AI reply was not valid JSON'; }
const usage = res.usage || {};
// Assumed prices for claude-sonnet-5: $2 input / $10 output per million tokens. Estimate; check current pricing.
const cost = ((usage.input_tokens || 0) * 2 + (usage.output_tokens || 0) * 10) / 1e6;
return { json: { ...src, ...{
  customer: f.customerName || '', phone: (f.phones || [])[0] || '', address: f.address || '', zip: f.zip || '',
  claim: f.claimNumber || '', claim_to_follow: !!f.claimToFollow, vendor_id: f.vendorId || 'V0', trade: f.trade || '',
  equipment: f.equipment || '', problem: f.problemSummary || '', urgency: f.urgency || 'Normal',
  parse_error, cost_usd: Number(cost.toFixed(5)),
} } };

// The AI call failed after all retries. Never drop the email: send it to a person.
const src = $('Build email text').item.json;
const err = $json.error?.message || $json.error || 'unknown error';
return { json: { ...src, route: 'person', checks_passed: 0, checks_failed: 0, duplicate_of: '', recall_of: '',
  reasons: 'AI extraction failed after 3 tries: ' + err, next_step: 'Read the email and create the ticket by hand.',
  ticket_id: '', action: (src.shadow ? 'WOULD send to a person: ' : 'Sent to a person: ') + 'AI extraction failed',
  cost_usd: 0, logged_at: new Date().toISOString() } };

// Validation rules on every field. Each rule: pass / warn / fail with a plain-English reason.
// Any failed rule means the ticket is NOT created automatically.
const t = $json;
const AREA = [80011, 80016];
const FORMATS = { V1: [/^NS-\d{6}$/, 'NS-######', 'Northstar'], V2: [/^BP\d{7}$/, 'BP#######', 'Bluepeak'], V3: [/^HAC-\d{5}$/, 'HAC-#####', 'Harbor'] };
const rules = [];
const add = (id, ok, reason, warn) => rules.push({ id, status: ok ? (warn ? 'warn' : 'pass') : 'fail', reason });
const digits = String(t.phone).replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
add('name', /[A-Za-z]{2,}/.test(t.customer), t.customer ? `Found "${t.customer}"` : 'No customer name');
add('phone', digits.length === 10, t.phone ? `"${t.phone}" has ${digits.length} digits; needs 10` : 'No phone number');
add('address', /^\d+[A-Za-z]?\s+[A-Za-z]/.test(String(t.address).trim()), t.address ? `"${t.address}"` : 'No service address');
const zipOk = /^\d{5}$/.test(String(t.zip));
add('zip', zipOk, zipOk ? `${t.zip} is 5 digits` : `"${t.zip || ''}" is not a 5-digit ZIP`);
add('area', zipOk && +t.zip >= AREA[0] && +t.zip <= AREA[1], zipOk ? `${t.zip} ${+t.zip >= AREA[0] && +t.zip <= AREA[1] ? 'is inside' : 'is outside'} the service area (80011-80016)` : 'No valid ZIP to check');
const fmt = FORMATS[t.vendor_id];
const claim = String(t.claim || '').toUpperCase();
if (!fmt) add('claim', true, 'Direct customer: no claim needed');
else if (fmt[0].test(claim)) add('claim', true, `${claim} matches ${fmt[2]} format ${fmt[1]}`);
else if (!claim && t.claim_to_follow) add('claim', true, `${fmt[2]} says the claim number is to follow`, true);
else add('claim', false, claim ? `"${claim}" does not match ${fmt[2]} format ${fmt[1]}` : `${fmt[2]} jobs need a claim number (${fmt[1]}) or "to follow"`);
add('trade', ['HVAC', 'Plumbing', 'Appliance'].includes(t.trade), t.trade ? `${t.trade}` : 'Trade not worked out');
add('problem', String(t.problem).trim().length >= 8, 'Problem described');
if (t.parse_error) add('ai_reply', false, t.parse_error);
const failed = rules.filter(r => r.status === 'fail');
return { json: { ...t, rules, checks_passed: rules.length - failed.length, checks_failed: failed.length,
  failed_rules: failed.map(r => `${r.id}: ${r.reason}`).join('; ') } };

// Duplicate & return-visit check against the Jobs sheet, then decide the route.
// duplicate: same claim on an open job, or same phone/address with an open job for the same trade.
// return visit: same phone/address, same trade, job completed in the last 30 days.
const OPEN = ['new', 'scheduled', 'en_route', 'in_progress', 'waiting_parts', 'waiting for a person'];
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const digits = s => String(s || '').replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
const addr = s => String(s || '').toLowerCase().replace(/[.,#]/g, ' ').replace(/\s+/g, ' ').trim();
let nextNo = Math.max(1065, ...rows.map(r => Number(String(r.id).replace(/\D/g, '')) || 0)) + 1;
const now = Date.now();
return $('Validate fields').all().map(item => {
  const t = item.json;
  const dup = [], recall = [];
  for (const r of rows) {
    const sameClaim = t.claim && r.claim && String(r.claim).toUpperCase() === String(t.claim).toUpperCase();
    const sameCust = (digits(t.phone).length === 10 && digits(r.phone) === digits(t.phone)) || (t.address && addr(r.address) === addr(t.address));
    const open = OPEN.includes(String(r.status).toLowerCase());
    const days = r.completed_at ? (now - new Date(r.completed_at)) / 86400000 : null;
    if (sameClaim && open) dup.push(`${r.id} (same claim ${t.claim})`);
    else if (sameCust && open && r.trade === t.trade) dup.push(`${r.id} (open ${r.trade} job: ${r.issue})`);
    else if (sameCust && !open && days !== null && days <= 30 && r.trade === t.trade) recall.push(`${r.id} (${r.issue}, completed ${Math.round(days)} days ago)`);
  }
  const reasons = [];
  if (t.urgency === 'Emergency') reasons.push('Emergency: call the customer now');
  if (dup.length) reasons.push('Possible duplicate of ' + dup.join(', '));
  if (recall.length) reasons.push('Return visit (warranty recall risk): ' + recall.join(', '));
  if (t.checks_failed) reasons.push('Failed checks: ' + t.failed_rules);
  const route = reasons.length ? 'person' : 'create';
  const next_step = t.urgency === 'Emergency' ? 'Call the customer now and dispatch the on-call tech.'
    : dup.length ? `Do not create a second ticket: add this email to ${dup[0].split(' ')[0]} and reject.`
    : recall.length ? `Book as a recall on ${recall[0].split(' ')[0]} with the same tech, no new trip charge.`
    : t.checks_failed ? 'Fix the failed fields (reply to the sender if needed), then create the ticket.' : '';
  const ticket_id = route === 'create' ? 'SH-' + (nextNo++) : '';
  const action = route === 'create'
    ? (t.shadow ? `WOULD create ticket ${ticket_id}` : `Created ticket ${ticket_id}`)
    : (t.shadow ? `WOULD send to a person: ${reasons[0]}` : `Sent to a person: ${reasons[0]}`);
  return { json: { ...t, rules: undefined, duplicate_of: dup.join('; '), recall_of: recall.join('; '), route,
    reasons: reasons.join(' | '), next_step, ticket_id, action, logged_at: new Date().toISOString() } };
});
